{
  "units": [
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "background",
      "meaning": "29 CFR 825.110 provides regulations defining and governing 'Eligible employee' under the Family and Medical Leave Act (FMLA), serving as a descriptive section heading without independent operative requirements."
    },
    {
      "quote_ref": "F001:F004",
      "scope_refs": [],
      "kind": "definition",
      "meaning": "An 'eligible employee' under the FMLA is defined as an employee of a covered employer who simultaneously satisfies three criteria: (1) has been employed by the employer for at least 12 months; (2) has been employed for at least 1,250 hours of service during the 12-month period immediately preceding the commencement of the leave (subject to special rules for airline flight crew employees in § 825.801); and (3) is employed at a worksite where 50 or more employees are employed by the employer within 75 miles of that worksite (referencing § 825.105(b) for employees working outside the U.S.)."
    },
    {
      "quote_ref": "F005",
      "scope_refs": [
        "F001:F002"
      ],
      "kind": "permission",
      "meaning": "The 12 months that an employee must have been employed by the employer to meet the FMLA eligibility requirement do not need to be consecutive months, subject to the conditions and break-in-service rules set forth in paragraph (b)."
    },
    {
      "quote_ref": "F006",
      "scope_refs": [
        "F001:F002",
        "F005"
      ],
      "kind": "exception",
      "meaning": "Subject to the exceptions specified in paragraph (b)(2), employment periods prior to a break in service of seven years or more are not required to be counted when determining whether an employee has been employed by the employer for at least 12 months."
    },
    {
      "quote_ref": "F007:F008",
      "scope_refs": [
        "F001:F002",
        "F005"
      ],
      "kind": "requirement",
      "meaning": "Employment periods preceding a break in service of more than seven years must be counted toward the 12-month employment requirement if the employee's break in service is occasioned by the fulfillment of a Uniformed Services Employment and Reemployment Rights Act (USERRA) covered service obligation. Furthermore, the period of absence from work due to or necessitated by USERRA-covered service must also be counted in determining whether the employee has been employed for at least 12 months, although this section provides no greater entitlement than available under USERRA."
    },
    {
      "quote_ref": "F007:F009",
      "scope_refs": [
        "F001:F002",
        "F005"
      ],
      "kind": "requirement",
      "meaning": "Employment periods preceding a break in service of more than seven years must be counted toward the 12-month employment requirement where a written agreement, including a collective bargaining agreement, exists concerning the employer's intention to rehire the employee after the break in service (such as for the purpose of furthering education or childrearing)."
    },
    {
      "quote_ref": "F010",
      "scope_refs": [
        "F001:F002",
        "F005"
      ],
      "kind": "definition",
      "meaning": "If an employee is maintained on the payroll for any part of a week—including any periods of paid or unpaid leave (such as sick leave or vacation) during which other benefits or compensation (e.g., workers' compensation, group health plan benefits) are provided by the employer—that week counts as a week of employment. For determining whether intermittent, occasional, or casual employment qualifies as at least 12 months, 52 weeks is deemed equal to 12 months."
    },
    {
      "quote_ref": "F011",
      "scope_refs": [
        "F001:F002",
        "F005"
      ],
      "kind": "permission",
      "meaning": "Employers are permitted to consider an employee's employment prior to a continuous break in service of more than seven years when determining whether the employee has met the 12-month employment requirement, even when not mandated to do so."
    },
    {
      "quote_ref": "F011",
      "scope_refs": [
        "F001:F002",
        "F005"
      ],
      "kind": "requirement",
      "meaning": "If an employer chooses to recognize prior employment before a continuous break in service of more than seven years, the employer must do so uniformly with respect to all employees with similar breaks in service."
    },
    {
      "quote_ref": "F012",
      "scope_refs": [
        "F001",
        "F003"
      ],
      "kind": "requirement",
      "meaning": "Except as provided in paragraph (c)(2) and § 825.801 for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service during the 12-month period is determined according to Fair Labor Standards Act (FLSA) principles for determining compensable hours of work (29 CFR part 785). The determining factor is the actual number of hours worked within the meaning of the FLSA; the determination is not limited by methods of recordkeeping or inaccurate compensation agreements, and any accurate accounting of actual hours worked under FLSA principles may be used."
    },
    {
      "quote_ref": "F013",
      "scope_refs": [
        "F001",
        "F003"
      ],
      "kind": "requirement",
      "meaning": "An employee returning from USERRA-covered service must be credited with the hours of service that would have been performed but for the period of absence from work due to or necessitated by USERRA-covered service when determining eligibility for FMLA-qualifying leave, adding those hours to hours actually worked during the previous 12-month period. To calculate the hours that would have been worked during that absence, the employee's pre-service work schedule can generally be used (with special rules in § 825.801(c) for airline flight crew employees)."
    },
    {
      "quote_ref": "F014",
      "scope_refs": [
        "F001",
        "F003"
      ],
      "kind": "requirement",
      "meaning": "If an employer does not maintain an accurate record of hours worked by an employee—including employees exempt from FLSA recordkeeping requirements, such as bona fide executive, administrative, and professional employees—the employer bears the burden of showing that the employee has not worked the requisite 1,250 hours. To claim such employees (e.g., full-time teachers who often work outside the classroom or at home) are ineligible for FMLA leave, the employer must be able to clearly demonstrate that the employee did not work 1,250 hours during the previous 12 months (subject to § 825.801(d) for airline flight crew employees)."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [
        "F001:F003"
      ],
      "kind": "requirement",
      "meaning": "The determination of whether an employee meets the 1,250 hours of service requirement and has been employed for at least 12 months must be made as of the date the FMLA leave is to start."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [
        "F001:F003"
      ],
      "kind": "permission",
      "meaning": "An employee may be on non-FMLA leave at the time the 12-month eligibility requirement is met; in that event, any portion of the leave taken for an FMLA-qualifying reason after meeting the eligibility requirement is treated as FMLA leave."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [
        "F001",
        "F004"
      ],
      "kind": "requirement",
      "meaning": "Whether 50 employees are employed within 75 miles of the worksite to establish FMLA eligibility is determined at the time the employee gives notice of the need for leave."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [
        "F001",
        "F004"
      ],
      "kind": "prohibition",
      "meaning": "Once an employee is determined eligible in response to a notice of need for leave (whether taken all at once, intermittently, or on a reduced schedule), the employee's eligibility for that specific notice cannot be affected by any subsequent change in employee headcount at or within 75 miles of the worksite, and the employer is prohibited from terminating leave that has already started if the employee count drops below 50 (e.g., notice in August when 60 employees are employed requires granting leave starting in December even if headcount drops to 40)."
    }
  ]
}
